      this.utterance.onboundary = event => {
        if (event.name === "word") {
          const currentWord = text.slice(event.charIndex).split(" ")[0];
          this.highlightText(event.charIndex, currentWord);
        }
      };

      // Handle end of speech
      this.utterance.onend = () => {
        this.isReading = false;
        this.clearHighlight();
      };
