      const before = text.slice(0, charIndex);
      const after = text.slice(charIndex + currentWord.length);
      this.renderedText = `
        <span>${before}</span>
        <span style="background-color: rgba(0, 191, 166, 0.6); padding: 2px; border-radius: 3px;">
          ${currentWord}
        </span>
        <span>${after}</span>`;
